/**
 * DTOs matching contracts/openapi.yaml schemas.
 * All identifiers use pseudonyms (emp_*, prj_*, etc.) — no personal data.
 * Generated by hand from the contract; replace with openapi-typescript when ready.
 */

// ──── primitives ────

export type WeekKey = string; // ^[0-9]{4}-W(0[1-9]|[1-4][0-9]|5[0-3])$
export type Grade = 'J' | 'M' | 'S' | 'L' | 'P';
export type Level = 1 | 2 | 3 | 4 | 5;

// ──── pagination ────

export interface PageMeta {
  limit: number;
  offset: number;
  total: number;
}

// ──── taxonomy ────

export type RoleFamily =
  | 'engineering'
  | 'quality'
  | 'data'
  | 'infrastructure'
  | 'product'
  | 'analysis'
  | 'design'
  | 'management'
  | 'security';

export type CompetencyCategory =
  | 'language'
  | 'framework'
  | 'database'
  | 'messaging'
  | 'cloud'
  | 'devops'
  | 'testing'
  | 'analytics'
  | 'ml'
  | 'architecture'
  | 'security'
  | 'process'
  | 'domain'
  | 'soft_skill';

export interface Role {
  role_id: string;
  name_en: string;
  name_ru: string;
  family: RoleFamily;
  synonyms: string[];
  core_competencies: string[];
  typical_grades: Grade[];
}

export interface Competency {
  competency_id: string;
  name_en: string;
  name_ru: string;
  category: CompetencyCategory;
  synonyms: string[];
  roles: string[];
  level_scale: 5;
}

// ──── reference ────

export interface GradeBand {
  grade: Grade;
  label_ru: string;
  cost_coefficient: number;
  typical_level_range: [Level, Level];
}

export interface Weights {
  M1: number;
  M2: number;
  M3: number;
  M4?: number;
  M5: number;
  M6: number;
  M7: number;
  M8: number;
  M9: number;
  M10: number;
  M11: number;
  M12: number;
}

export type PresetName = 'fast' | 'economical' | 'balanced' | 'low_risk';

export interface WeightPreset {
  preset: PresetName;
  label_ru: string;
  weights: Weights;
  sum_check: number;
}

export interface PlanningParams {
  time_model: {
    week_start: 'monday';
    working_days_per_week: 5;
    hours_per_day: 8;
    weekly_hours_norm: 40;
    reserve_ratio: number;
    calendar: string;
  };
  schedule: {
    monte_carlo_runs: number;
    monte_carlo_seed: number;
    portfolio_tau_working_days: number;
  };
  solver: {
    default_time_limit_ms: number;
    recalc_time_limit_ms: number;
    k_min: number;
    k_max: number;
    min_jaccard_diversity: number;
  };
  limits: {
    max_employees: number;
    max_requirements: number;
  };
  metrics_version: string;
}

// ──── employees ────

export type EmploymentType = 'internal' | 'contractor' | 'external_partner';

export interface CapacityProfile {
  weekly_hours_norm: number;
  reserve_ratio: number;
  max_utilization_ratio: number;
}

export interface Employee {
  employee_id: string;
  grade: Grade;
  role_profile_id: string;
  unit_id: string;
  employment_type: EmploymentType;
  bench_flag: boolean;
  capacity_profile: CapacityProfile;
  cost_coefficient: number;
  active: boolean;
}

export type CompetencySource =
  | 'self_assessment'
  | 'manager_review'
  | 'project_history'
  | 'certification'
  | 'hr_import';

export interface EmployeeCompetency {
  competency_id: string;
  level: Level;
  confidence: number;
  last_used?: string;
  source: CompetencySource;
}

export interface CapacityWeek {
  employee_id: string;
  week: WeekKey;
  working_days: number;
  norm_hours: number;
  reserved_hours: number;
  assigned_hours: number;
  absence_hours: number;
  free_hours: number;
  load_ratio: number;
  unavailable: boolean;
}

// ──── projects ────

export type ProjectStatus = 'planned' | 'active' | 'paused' | 'done' | 'cancelled';
export type ProjectCriticality = 'critical' | 'high' | 'normal' | 'low';

export interface Project {
  project_id: string;
  code: string;
  name: string;
  status: ProjectStatus;
  priority: number;
  criticality: ProjectCriticality;
  start_week: WeekKey;
  end_week_planned: WeekKey;
  end_week_forecast?: WeekKey;
  replaces_other_projects: boolean;
}

export type AssignmentSource = 'plan' | 'actual' | 'forecast';

export interface Assignment {
  assignment_id: string;
  project_id: string;
  employee_id: string;
  role_id: string;
  week: WeekKey;
  hours: number;
  source: AssignmentSource;
}

// ──── absences ────

export type AbsenceType =
  | 'vacation'
  | 'sick_leave'
  | 'training'
  | 'business_trip'
  | 'parental_leave'
  | 'other';

export type AbsenceSource = 'manual' | 'hr_import' | 'calendar_import';

export interface Absence {
  absence_id: string;
  employee_id: string;
  type: AbsenceType;
  start_date: string; // format: date
  end_date: string;
  hours_per_day: number;
  approved: boolean;
  source: AbsenceSource;
}
